import{_ as o,a0 as p,w as d,s as r,I as i,x as e,a1 as a,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Linux 遠程連接之 SSH 新手指南 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 遠程連接之 SSH 新手指南 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 遠程連接之 SSH 新手指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 遠程連接之 SSH 新手指南 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20200907 A beginner-s guide to SSH for remote connection on Linux","title":"Linux 遠程連接之 SSH 新手指南","tag":"202108","desc":""},"relativePath":"202108/20200907 A beginner-s guide to SSH for remote connection on Linux.md","filePath":"[post].md"}'),h={name:"202108/20200907 A beginner-s guide to SSH for remote connection on Linux.md"};function g(c,s,u,b,k,S){const n=p("Link");return d(),r("div",null,[s[23]||(s[23]=i("h1",{id:"linux-遠程連接之-ssh-新手指南",tabindex:"-1"},[e("Linux 遠程連接之 SSH 新手指南 "),i("a",{class:"header-anchor",href:"#linux-遠程連接之-ssh-新手指南","aria-label":"Permalink to “Linux 遠程連接之 SSH 新手指南”"},"​")],-1)),s[24]||(s[24]=i("blockquote",null,[i("p",null,"學會使用安全外殼協議連接遠程計算機。")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/28/105409ztj7akfjpcluwjp3.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=e("使用 Linux，你只需要在鍵盤上輸入命令，就可以巧妙地使用計算機（甚至這台計算機可以在世界上任何地方），這正是 Linux 最吸引人的特性之一。有了 OpenSSH，",-1)),a(n,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:t(()=>[...s[0]||(s[0]=[e("POSIX",-1)])]),_:1}),s[2]||(s[2]=e(" 用户就可以在有權限連接的計算機上打開安全外殼協議，然後遠程使用。這對於許多 Linux 用户來説可能不過是日常任務，但從沒操作過的人可能就會感到很困惑。本文介紹瞭如何配置兩台計算機的 ",-1)),s[3]||(s[3]=i("ruby",null,[e("安全外殼協議"),i("rt",null,"secure shell")],-1)),s[4]||(s[4]=e("（簡稱 SSH）連接，以及如何在沒有密碼的情況下安全地從一台計算機連接到另一台計算機。",-1))]),s[26]||(s[26]=l(`<h3 id="相關術語" tabindex="-1">相關術語 <a class="header-anchor" href="#相關術語" aria-label="Permalink to “相關術語”">​</a></h3><p>在討論多台計算機時，如何將不同計算機彼此區分開可能會讓人頭疼。IT 社區擁有完善的術語來描述計算機聯網的過程。</p><ul><li><ruby>服務<rt>service</rt></ruby>： 服務是指在後台運行的軟件，因此它不會侷限於僅供安裝它的計算機使用。例如，Web 服務器通常託管着 Web 共享 <em>服務</em>。該術語暗含（但非絕對）它是沒有圖形界面的軟件。</li><li><ruby>主機<rt>host</rt></ruby>： 主機可以是任何計算機。在 IT 中，任何計算機都可以稱為 <em>主機</em>，因為從技術上講，任何計算機都可以<ruby>託管<rt>host</rt></ruby>對其他計算機有用的應用程序。你可能不會把自己的筆記本電腦視為 <strong>主機</strong>，但其實上面可能正運行着一些對你、你的手機或其他計算機有用的服務。</li><li><ruby>本地<rt>local</rt></ruby>： 本地計算機是指用户或某些特定軟件正在使用的計算機。例如，每台計算機都會把自己稱為 <code>localhost</code>。</li><li><ruby>遠程<rt>remote</rt></ruby>： 遠程計算機是指你既沒在其面前，也沒有在實際使用的計算機，是真正意義上在 <em>遠程</em> 位置的計算機。</li></ul><p>現在術語已經明確好，我們可以開始了。</p><h3 id="在每台主機上激活-ssh" tabindex="-1">在每台主機上激活 SSH <a class="header-anchor" href="#在每台主機上激活-ssh" aria-label="Permalink to “在每台主機上激活 SSH”">​</a></h3><p>要通過 SSH 連接兩台計算機，每個主機都必須安裝 SSH。SSH 有兩個組成部分：本地計算機上使用的用於啓動連接的命令，以及用於接收連接請求的 <em>服務器</em>。有些計算機可能已經安裝好了 SSH 的一個或兩個部分。驗證 SSH 是否完全安裝的命令因系統而異，因此最簡單的驗證方法是查閲相關配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file /etc/ssh/ssh_config</span></span>
<span class="line"><span>/etc/ssh/ssh_config: ASCII text</span></span></code></pre></div><p>如果返回 <code>No such file or directory</code> 錯誤，説明沒有安裝 SSH 命令。</p><p>SSH 服務的檢測與此類似（注意文件名中的 <code>d</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file /etc/ssh/sshd_config</span></span>
<span class="line"><span>/etc/ssh/sshd_config: ASCII text</span></span></code></pre></div><p>根據缺失情況選擇安裝兩個組件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install openssh-clients openssh-server</span></span></code></pre></div><p>在遠程計算機上，使用 systemd 命令啓用 SSH 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now sshd</span></span></code></pre></div><p>你也可以在 GNOME 上的 <strong>系統設置</strong> 或 macOS 上的 <strong>系統首選項</strong> 中啓用 SSH 服務。在 GNOME 桌面上，該設置位於 <strong>共享</strong> 面板中：</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-activate-remote-login.png" alt="在 GNOME 系統設置中激活 SSH" title="Activate SSH in GNOME System Settings"></p><h3 id="開啓安全外殼協議" tabindex="-1">開啓安全外殼協議 <a class="header-anchor" href="#開啓安全外殼協議" aria-label="Permalink to “開啓安全外殼協議”">​</a></h3><p>現在你已經在遠程計算機上安裝並啓用了 SSH，可以嘗試使用密碼登錄作為測試。要訪問遠程計算機，你需要有用户帳户和密碼。</p><p>遠程用户不必與本地用户相同。只要擁有相應用户的密碼，你就可以在遠程機器上以任何用户的身份登錄。例如，我在我的工作計算機上的用户是 <code>sethkenlon</code> ，但在我的個人計算機上是 <code>seth</code>。如果我正在使用我的個人計算機（即作為當前的本地計算機），並且想通過 SSH 連接到我的工作計算機，我可以通過將自己標識為 <code>sethkenlon</code> 並使用我的工作密碼來實現連接。</p><p>要通過 SSH 連接到遠程計算機，你必須知道其 IP 地址或可解析的主機名。在遠程計算機上使用 <code>ip</code> 命令可以查看該機器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr show | grep &quot;inet &quot;</span></span>
<span class="line"><span>inet 127.0.0.1/8 scope host lo</span></span>
<span class="line"><span>inet 10.1.1.5/27 brd 10.1.1.31 [...]</span></span></code></pre></div><p>如果遠程計算機沒有 <code>ip</code> 命令，可以嘗試使用 <code>ifconfig</code> 命令（甚至可以試試 Windows 上通用的 <code>ipconfig</code> 命令）。</p>`,22)),i("p",null,[s[6]||(s[6]=l("<code>127.0.0.1</code> 是一個特殊的地址，它實際上是 <code>localhost</code> 的地址。這是一個<ruby>環回<rt>loopback</rt></ruby>地址，系統使用它來找到自己。這在登錄遠程計算機時並沒有什麼用，因此在此示例中，遠程計算機的正確 IP 地址為 <code>10.1.1.5</code>。在現實生活中，我的本地網絡正在使用 <code>10.1.1.0</code> 子網，進而可得知前述正確的 IP 地址。如果遠程計算機在不同的網絡上，那麼 IP 地址幾乎可能是任何地址（但絕不會是 <code>127.0.0.1</code>），並且可能需要一些特殊的路由才能通過各種防火牆到達遠程。如果你的遠程計算機在同一個網絡上，但想要訪問比自己的網絡更遠的計算機，請閲讀我之前寫的關於 ",12)),a(n,{href:"https://opensource.com/article/20/8/open-ports-your-firewall"},{default:t(()=>[...s[5]||(s[5]=[e("在防火牆中打開端口",-1)])]),_:1}),s[7]||(s[7]=e(" 的文章。",-1))]),s[27]||(s[27]=l(`<p>如果你能通過 IP 地址 <em>或</em> 主機名 <code>ping</code> 到遠程機器，並且擁有登錄帳户，那麼就可以通過 SSH 接入遠程機器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 10.1.1.5</span></span>
<span class="line"><span>PING 10.1.1.5 (10.1.1.5) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 10.1.1.5: icmp_seq=1 ttl=64 time=4.66 ms</span></span>
<span class="line"><span>$ ping -c1 akiton.local</span></span>
<span class="line"><span>PING 10.1.1.5 (10.1.1.5) 56(84) bytes of data.</span></span></code></pre></div><p>至此就成功了一小步。再試試使用 SSH 登錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whoami</span></span>
<span class="line"><span>seth</span></span>
<span class="line"><span>$ ssh sethkenlon@10.1.1.5</span></span>
<span class="line"><span>bash$ whoami</span></span>
<span class="line"><span>sethkenlon</span></span></code></pre></div><p>測試登錄有效，下一節會介紹如何激活無密碼登錄。</p><h3 id="創建-ssh-密鑰" tabindex="-1">創建 SSH 密鑰 <a class="header-anchor" href="#創建-ssh-密鑰" aria-label="Permalink to “創建 SSH 密鑰”">​</a></h3><p>要在沒有密碼的情況下安全地登錄到另一台計算機，登錄者必須擁有 SSH 密鑰。可能你的機器上已經有一個 SSH 密鑰，但再多創建一個新密鑰也沒有什麼壞處。SSH 密鑰的生命週期是在本地計算機上開始的，它由兩部分組成：一個是永遠不會與任何人或任何東西共享的私鑰，一個是可以複製到任何你想要無密碼訪問的遠程機器上的公鑰。</p><p>有的人可能會創建一個 SSH 密鑰，並將其用於從遠程登錄到 GitLab 身份驗證的所有操作，但我會選擇對不同的任務組使用不同的密鑰。例如，我在家裏使用一個密鑰對本地機器進行身份驗證，使用另一個密鑰對我維護的 Web 服務器進行身份驗證，再一個單獨的密鑰用於 Git 主機，以及又一個用於我託管的 Git 存儲庫，等等。在此示例中，我將只創建一個唯一密鑰，以在局域網內的計算機上使用。</p><p>使用 <code>ssh-keygen</code> 命令創建新的 SSH 密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-keygen -t ed25519 -f ~/.ssh/lan</span></span></code></pre></div><p><code>-t</code> 選項代表 <em>類型</em> ，上述代碼設置了一個高於默認值的密鑰加密級別。<code>-f</code> 選項代表 <em>文件</em>，指定了密鑰的文件名和位置。運行此命令後會生成一個名為 <code>lan</code> 的 SSH 私鑰和一個名為 <code>lan.pub</code> 的 SSH 公鑰。</p><p>使用 <code>ssh-copy-id</code> 命令把公鑰發送到遠程機器上，在此之前要先確保具有遠程計算機的 SSH 訪問權限。如果你無法使用密碼登錄遠程主機，也就無法設置無密碼登錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-copy-id -i ~/.ssh/lan.pub sethkenlon@10.1.1.5</span></span></code></pre></div><p>過程中系統會提示你輸入遠程主機上的登錄密碼。</p><p>操作成功後，使用 <code>-i</code> 選項將 SSH 命令指向對應的密鑰（在本例中為 <code>lan</code>）再次嘗試登錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -i ~/.ssh/lan sethkenlon@10.1.1.5</span></span>
<span class="line"><span>bash$ whoami</span></span>
<span class="line"><span>sethkenlon</span></span></code></pre></div><p>對局域網上的所有計算機重複此過程，你就將能夠無密碼訪問這個局域網上的每台主機。實際上，一旦你設置了無密碼認證，你就可以編輯 <code>/etc/ssh/sshd_config</code> 文件來禁止密碼認證。這有助於防止其他人使用 SSH 對計算機進行身份驗證，除非他們擁有你的私鑰。要想達到這個效果，可以在有 <code>sudo</code> 權限的文本編輯器中打開 <code>/etc/ssh/sshd_config</code> 並搜索字符串 <code>PasswordAuthentication</code>，將默認行更改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PasswordAuthentication no</span></span></code></pre></div><p>保存並重啓 SSH 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart sshd &amp;amp;&amp;amp; echo &quot;OK&quot;</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="日常使用-ssh" tabindex="-1">日常使用 SSH <a class="header-anchor" href="#日常使用-ssh" aria-label="Permalink to “日常使用 SSH”">​</a></h3><p>OpenSSH 改變了人們對操作計算機的看法，使用户不再被束縛在面前的計算機上。使用 SSH，你可以訪問家中的任何計算機，或者擁有帳户的服務器，甚至是移動和物聯網設備。充分利用 SSH 也意味着解鎖 Linux 終端的更多用途。如果你還沒有使用過 SSH，請試一下它吧。試着適應 SSH，創建一些適當的密鑰，以此更安全地使用計算機，打破必須與計算機面對面的侷限性。</p><hr>`,23)),i("p",null,[s[9]||(s[9]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/20/9/ssh"},{default:t(()=>[...s[8]||(s[8]=[e("https://opensource.com/article/20/9/ssh",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[10]||(s[10]=[e("Seth Kenlon",-1)])]),_:1}),s[15]||(s[15]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[11]||(s[11]=[e("lujun9972",-1)])]),_:1}),s[16]||(s[16]=e(" 譯者：",-1)),a(n,{href:"https://github.com/unigeorge"},{default:t(()=>[...s[12]||(s[12]=[e("unigeorge",-1)])]),_:1}),s[17]||(s[17]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[e("LCTT",-1)])]),_:1}),s[21]||(s[21]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[e("Linux中國",-1)])]),_:1}),s[22]||(s[22]=e(" 榮譽推出",-1))])])}const x=o(h,[["render",g]]);export{y as __pageData,x as default};
